CREATE TABLE workspace_records(site_id TEXT PRIMARY KEY, config_json TEXT NOT NULL, disabled INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL);
CREATE TABLE content_jobs(id TEXT PRIMARY KEY,site_id TEXT NOT NULL,slug TEXT NOT NULL,title TEXT NOT NULL,category TEXT NOT NULL,request_json TEXT NOT NULL,article_json TEXT,quality_json TEXT,remote_json TEXT,status TEXT NOT NULL DEFAULT 'queued',publish_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,error TEXT,UNIQUE(site_id,slug));
CREATE INDEX content_jobs_due ON content_jobs(status,publish_at);
CREATE TABLE scheduler_runs(id TEXT PRIMARY KEY,site_id TEXT,job_id TEXT,phase TEXT NOT NULL,status TEXT NOT NULL,message TEXT,created_at TEXT NOT NULL);
CREATE TABLE publication_receipts(job_id TEXT NOT NULL,lang TEXT NOT NULL,phase TEXT NOT NULL,remote_json TEXT,updated_at TEXT NOT NULL,PRIMARY KEY(job_id,lang,phase));
ALTER TABLE topic_ideas ADD COLUMN brief_json TEXT;
INSERT INTO workspace_records(site_id,config_json,updated_at) VALUES('korea-buy-list','{"site_id": "korea-buy-list", "name": "Korea Buy List", "description": "영어·일본어 독자를 위한 한국 쇼핑 가이드", "site_url": "https://koreabuylist.blogspot.com", "languages": ["en", "ja"], "categories": ["shopping", "stays", "transport", "practical"], "integration": "blogger", "admin_url": "https://www.blogger.com/blog/posts/2501831991285091849", "strategy": {"min_score": 70, "required_images": 4, "affiliate_disclosure": "Affiliate links may earn a commission at no extra cost to you.", "source_domains": ["global.oliveyoung.com", "english.visitkorea.or.kr", "english.visitseoul.net", "airport.kr"], "audience": "English-speaking and Japanese visitors shopping in Korea, researched independently by audience", "voice": "Practical shopping evidence. EN uses Korea ranking; JA uses Japan-destination ranking. Prices require currency, quantity, source and checked date. No invented affiliate codes.", "pillars": ["Korea shopping decisions", "Shopping-friendly stays", "Airport and shopping transport", "Practical first-visit questions"], "entities": ["Seoul", "Olive Young", "Incheon Airport"], "templates": [{"title": "How to compare Korean skincare prices without misleading discounts", "category": "shopping", "keyword": "Korea skincare price comparison", "format": "comparison"}, {"title": "Which Seoul area should shoppers stay in?", "category": "stays", "keyword": "Seoul shopping hotel areas", "format": "guide"}, {"title": "How do you get from Incheon Airport to Seoul?", "category": "transport", "keyword": "Incheon airport Seoul transport", "format": "comparison"}]}, "connection": {"url_env": "BLOGGER_SITE_URL", "key_env": "BLOGGER_ACCESS_TOKEN", "blog_id": "2501831991285091849", "client_id_env": "BLOGGER_CLIENT_ID", "client_secret_env": "BLOGGER_CLIENT_SECRET", "refresh_token_env": "BLOGGER_REFRESH_TOKEN"}, "schedule": {"enabled": false, "interval_days": 2, "hour_kst": 10, "minute": 0, "next_run": "", "mode": "publish", "auto_generate": true}, "site_url_env": "BLOGGER_SITE_URL"}','2026-10-05T00:00:00Z');
INSERT INTO workspace_records(site_id,config_json,updated_at) VALUES('koreabylocal','{"site_id": "koreabylocal", "name": "Korea by Local", "description": "현지의 시선으로 전하는 한국 여행과 경험", "site_url": "https://koreabylocal.com", "article_path": "/guidebook/{slug}", "languages": ["en"], "categories": ["NEWS", "LOCALS", "KOREAN", "K-CULTURE"], "integration": "supabase", "admin_url": "https://koreabylocal.com/admin/blog", "strategy": {"min_score": 70, "required_images": 1, "affiliate_disclosure": "", "source_domains": ["english.visitkorea.or.kr", "english.visitseoul.net"], "audience": "Foreign visitors seeking local Korean experiences", "voice": "A local guide, concise and concrete; explain local terms and practical steps with official dated sources.", "pillars": ["Local neighbourhood experiences", "Korean everyday language", "Seasonal local events", "Cultural context"], "entities": ["Seoul", "Busan", "Korean culture"], "templates": [{"title": "How do you plan a local Seoul neighbourhood walk?", "category": "LOCALS", "keyword": "Seoul local neighbourhood walk", "format": "guide"}, {"title": "What Korean phrases help first-time visitors?", "category": "KOREAN", "keyword": "Korean phrases first visitors", "format": "definition"}, {"title": "How should visitors check Korean seasonal event dates?", "category": "NEWS", "keyword": "Korea seasonal event dates", "format": "guide"}]}, "connection": {"url_env": "NATIVE_BLOG_SUPABASE_URL", "key_env": "NATIVE_BLOG_SUPABASE_KEY", "schema": "koreabylocal", "table": "blog_posts", "template": "koreabylocal"}, "schedule": {"enabled": false, "interval_days": 2, "hour_kst": 10, "minute": 0, "next_run": "", "mode": "publish", "auto_generate": true}, "site_url_env": "KOREABYLOCAL_SITE_URL"}','2026-10-05T00:00:00Z');
INSERT INTO workspace_records(site_id,config_json,updated_at) VALUES('koreadecode','{"site_id": "koreadecode", "name": "Korea Decode", "description": "세계의 독자에게 풀어주는 한국 문화와 트렌드", "site_url": "https://koreadecode.com", "languages": ["en"], "categories": ["News", "K-Pop", "K-Beauty", "K-Food", "Travel", "Culture"], "integration": "supabase", "admin_url": "https://koreadecode.com/admin/", "strategy": {"min_score": 70, "required_images": 1, "affiliate_disclosure": "", "source_domains": ["english.visitkorea.or.kr", "english.visitseoul.net"], "audience": "English readers exploring Korean culture and trends", "voice": "Explain the why and cultural context. Distinguish evidence from opinion. No invented rankings, dates or claims.", "pillars": ["Korean pop culture explained", "Beauty routines and product context", "Food and cultural etiquette", "Practical Korea travel"], "entities": ["Korean culture", "Seoul", "Korean food"], "templates": [{"title": "What is Korean food etiquette for first-time visitors?", "category": "K-Food", "keyword": "Korean food etiquette visitors", "format": "definition"}, {"title": "How do Korean skincare routines differ?", "category": "K-Beauty", "keyword": "Korean skincare routine comparison", "format": "comparison"}, {"title": "How do you interpret Korean cultural trends responsibly?", "category": "Culture", "keyword": "Korean culture trends explained", "format": "guide"}]}, "connection": {"url_env": "NATIVE_BLOG_SUPABASE_URL", "key_env": "NATIVE_BLOG_SUPABASE_KEY", "schema": "public", "table": "posts", "template": "koreadecode"}, "schedule": {"enabled": false, "interval_days": 2, "hour_kst": 10, "minute": 0, "next_run": "", "mode": "publish", "auto_generate": true}, "site_url_env": "KOREADECODE_SITE_URL"}','2026-10-05T00:00:00Z');
